sys_script_include.script:
var MSS_Record_Movement = Class.create();
MSS_Record_Movement.prototype = {
    initialize: function() {},


    updateTaskClassName: function(caseID, newTaskClassName) {
        try {
            if (!caseID || !newTaskClassName) {
                gs.error('updateTaskClassName: Missing caseID or newTaskClassName');
                return;
            }
            var taskGR = new GlideRecord('x_hsb11_mss_coll_0_collateral_task_table');
            taskGR.addQuery('collateral_case_id', caseID);
            taskGR.query();
            while (taskGR.next()) {
                taskGR.sys_class_name = newTaskClassName;

                var grCaseJournal = new global.UpdateComments();
                grCaseJournal.updateJournalField(taskGR.sys_id, newTaskClassName);
                //this.updateJournalField(taskGR.sys_id, newTaskClassName);
                taskGR.update();
            }
        } catch (e) {
            gs.error('updateTaskClassName Exception: ' + e.message);
        }
    },
    /**
     * Updates the assignment team for all case records matching the given caseID.
     * @param {String} caseID - The case number to update.
     * @param {String} assignmentTeam - The new assignment team value.
     * MSSCOLATRL-158
     */
    closeCaseRecord: function(caseID, assignmentTeam) {
        try {
            if (!caseID || !assignmentTeam) {
                gs.error('closeCaseRecord: Missing caseID or assignmentTeam');
                return;
            }
            var caseGR = new GlideRecord('x_hsb11_mss_coll_0_collateral_case_table');
            caseGR.addQuery('number', caseID);
            caseGR.query();
            while (caseGR.next()) {
                caseGR.u_assignment_team = assignmentTeam;
                caseGR.update();
            }
        } catch (e) {
            gs.error('closeCaseRecord Exception: ' + e.message);
        }
    },

	/**
     * Updates the state to Work in progress for all case records matching the given caseID.
     * @param {String} caseID - The case number to update.
     * @param {String} assignmentTeam - The new assignment team value.
     * MSSCOLATRL-158
     */
    updateStateCaseRecord: function(caseID) {
        try {
            if (!caseID) {
                gs.error('updateStateCaseRecord: Missing caseID');
                return;
            }
            var caseGR = new GlideRecord('x_hsb11_mss_coll_0_collateral_case_table');
            caseGR.addQuery('number', caseID);
            caseGR.query();
            while (caseGR.next()) {
				//gs.info("Updating the state of the case");
                caseGR.state = 2;
                caseGR.update();
            }
        } catch (e) {
            gs.error('updateStateCaseRecord Exception: ' + e.message);
        }
    },

    type: 'MSS_Record_Movement'
};
